CREATE SET TABLE MDP01_META.META_ETL_NOTIFICATION ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      notification_id INTEGER NOT NULL,      etl_job_id INTEGER,      notification_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      on_success CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      on_failure CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      on_warning CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      recipients VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      webhook_url VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      subject_template VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      body_template CLOB(16777216) CHARACTER SET UNICODE,      is_active CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( notification_id )INDEX ( etl_job_id );